package generator

import (
	"fmt"
	"io"
	"strings"
)

// WriteSisoConfig writes a companion Starlark config for executing the
// generated build graph with siso (https://go.chromium.org/build/siso), the
// drop-in Ninja replacement with native REAPI/RBE support.
//
// The generated file is a valid siso config module exposing the required
// init / input_deps / rules functions. Toolchain and sysroot hooks are filled
// in from the generator options so remote actions see the NDK compiler
// wrappers and headers; extend the maps by hand for project-specific sysroots
// (e.g. extracted APEX payloads under /apex/<pkg>/include).
func (g *Generator) WriteSisoConfig(w io.Writer) error {
	var b strings.Builder
	b.WriteString("# Generated by bp2ninja -siso\n")
	b.WriteString("# Companion Starlark config for the emitted build.ninja.\n")
	b.WriteString("#\n")
	b.WriteString("# Run the graph with siso instead of ninja:\n")
	b.WriteString("#   siso ninja -f build.ninja -C . --config siso.star\n")
	b.WriteString("#\n")
	b.WriteString("# The ninja file itself already carries siso rule bindings\n")
	b.WriteString("# (restat_content, sandbox_disabled and, with -siso-remote,\n")
	b.WriteString("# remote_enabled on pure compile actions). This config wires\n")
	b.WriteString("# toolchain / sysroot inputs and per-step overrides that cannot\n")
	b.WriteString("# be expressed as ninja bindings.\n")
	b.WriteString("#\n")
	b.WriteString("# Reference: https://chromium.googlesource.com/build/+/main/siso/docs/starlark_config.md\n\n")

	b.WriteString("def init(ctx):\n")
	b.WriteString("  return {}\n\n")

	b.WriteString("def input_deps(ctx):\n")
	b.WriteString("  deps = {}\n")
	if g.opts.NDKDir != "" {
		fmt.Fprintf(&b, "  # NDK toolchain wrappers pull in the sysroot headers so remote\n")
		fmt.Fprintf(&b, "  # compile actions upload the full toolchain context.\n")
		fmt.Fprintf(&b, "  deps[%q] = [%q]\n", g.toolchainBinDirHint(), g.sysrootHint())
	}
	b.WriteString("  # Extracted APEX / modular sysroots: add one entry per dev sysroot\n")
	b.WriteString("  # consumed via -I flags, e.g.\n")
	b.WriteString("  # deps[\"/apex/com.android.art/include\"] = [\"/apex/com.android.art\"]\n")
	b.WriteString("  return deps\n\n")

	b.WriteString("def rules(ctx):\n")
	b.WriteString("  return [\n")
	if g.opts.SisoRemote {
		b.WriteString("    # Compile actions are remote_enabled via ninja bindings;\n")
		b.WriteString("    # link / archive steps stay local because they consume\n")
		b.WriteString("    # prebuilt libraries outside the workspace.\n")
		b.WriteString("    {\"name\": \"link-local\", \"command_prefix\": \"\", \"output_local\": True},\n")
	}
	b.WriteString("  ]\n")
	_, err := io.WriteString(w, b.String())
	return err
}

// toolchainBinDirHint reports the NDK prebuilt bin directory used by the
// emitted $cc / $cxx / $ar variables, if resolvable from the options.
func (g *Generator) toolchainBinDirHint() string {
	for _, tool := range []string{g.opts.ClangPath, g.opts.ClangCxxPath, g.opts.ArPath} {
		if tool == "" {
			continue
		}
		if i := strings.LastIndex(tool, "/bin/"); i > 0 {
			return tool[:i+len("/bin")]
		}
	}
	if g.opts.NDKDir != "" {
		return g.opts.NDKDir + "/toolchains/llvm/prebuilt"
	}
	return ""
}

// sysrootHint reports the sysroot path the emitted graph compiles against.
func (g *Generator) sysrootHint() string {
	if g.opts.SysrootDir != "" {
		return g.opts.SysrootDir
	}
	if g.opts.NDKDir != "" {
		return g.opts.NDKDir + "/toolchains/llvm/prebuilt/linux-x86_64/sysroot"
	}
	return ""
}
